const items = $input.all();
if (items.length !== 1 || !items[0] || items[0].binary) throw new Error('INVALID_REPORT_ITEM');
const r = items[0].json;
const keys = ['schema','input_kind','attempts','unavailable_attempts','diagnostic','status','source_authorized','independently_verified','eligible_for_model_scoring','production_recommendations','external_calls'];
if (!r || typeof r !== 'object' || Array.isArray(r) || Object.keys(r).length !== keys.length || !keys.every(k => Object.prototype.hasOwnProperty.call(r,k))) throw new Error('INVALID_REPORT_FIELDS');
if (r.schema !== 'intelligence-x-rehearsal-v1' || r.input_kind !== 'OFFLINE_REPLAY' || r.status !== 'HOLD' || r.source_authorized !== false || r.independently_verified !== false || r.eligible_for_model_scoring !== false || r.production_recommendations !== 'DISABLED' || r.external_calls !== 0) throw new Error('UNSAFE_REPORT');
const n = r.attempts, u = r.unavailable_attempts;
if (!Number.isSafeInteger(n) || n < 1 || n > 3 || !Number.isSafeInteger(u) || u < 0 || u > n) throw new Error('INVALID_ATTEMPTS');
const d = r.diagnostic;
if (d === 'UNAVAILABLE' ? u !== n : !['AGREEMENT_CANDIDATE','BLOCKED'].includes(d) || u !== n-1) throw new Error('INVALID_DIAGNOSTIC');
return [{json:{schema:'intelligence-x-rehearsal-alert-v1',input_kind:'OFFLINE_REPLAY',attempts:n,unavailable_attempts:u,diagnostic:d,alert:d==='UNAVAILABLE'?'SOURCE_OUTAGE':d==='BLOCKED'?'DATA_REJECTED':u>0?'RECOVERED_RESEARCH_ONLY':'RESEARCH_ONLY',status:'HOLD',source_authorized:false,independently_verified:false,eligible_for_model_scoring:false,production_recommendations:'DISABLED',external_calls:0}}];
